create extension if not exists pgcrypto;
create type public.app_role as enum ('student','marketing');
create type public.request_status as enum ('Pending','Under Review','Approved','Rejected','Preparing','Ready for Pickup','Completed','Cancelled');

create table public.student_profiles(id uuid primary key references auth.users on delete cascade,student_id text unique not null,phinma_email text unique not null,full_name text not null,program text,year_level text,phone text,created_at timestamptz default now());
create table public.staff_profiles(id uuid primary key references auth.users on delete cascade,employee_id text unique not null,work_email text unique not null,full_name text not null,active boolean not null default true,created_at timestamptz default now());
create table public.uniform_products(id uuid primary key default gen_random_uuid(),name text not null,category text not null,description text,price numeric(10,2) not null check(price>=0),image text default 'shirt-outline',active boolean default true,created_at timestamptz default now());
create table public.product_sizes(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.uniform_products on delete cascade,label text not null,unique(product_id,label));
create table public.inventory(size_id uuid primary key references public.product_sizes on delete cascade,quantity_available integer not null default 0 check(quantity_available>=0),low_stock_threshold integer not null default 5 check(low_stock_threshold>=0),updated_at timestamptz default now());
create table public.pickup_locations(id uuid primary key default gen_random_uuid(),name text unique not null,address text,hours text,active boolean default true);
create table public.requests(id uuid primary key default gen_random_uuid(),reference text unique not null,student_id uuid not null references public.student_profiles(id),pickup_location_id uuid not null references public.pickup_locations(id),status public.request_status not null default 'Pending',total numeric(10,2) not null default 0,rejection_reason text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.request_items(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.requests on delete cascade,size_id uuid not null references public.product_sizes(id),quantity integer not null check(quantity>0),unit_price numeric(10,2) not null check(unit_price>=0),unique(request_id,size_id));
create table public.request_status_history(id bigint generated always as identity primary key,request_id uuid not null references public.requests on delete cascade,status public.request_status not null,note text,changed_by uuid references auth.users,created_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,title text not null,message text not null,read boolean default false,created_at timestamptz default now());
create table public.inventory_adjustments(id bigint generated always as identity primary key,size_id uuid not null references public.product_sizes,delta integer not null,reason text not null,performed_by uuid references auth.users,created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users,action text not null,entity_type text not null,entity_id text,metadata jsonb default '{}',created_at timestamptz default now());
create sequence public.request_reference_seq;

create or replace function public.is_marketing() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from staff_profiles where id=auth.uid() and active)$$;
create or replace function public.current_user_profile() returns jsonb language plpgsql security definer set search_path=public as $$declare r jsonb;begin select jsonb_build_object('id',id,'role','student','name',full_name,'identifier',student_id,'program',program,'year',year_level) into r from student_profiles where id=auth.uid();if r is null then select jsonb_build_object('id',id,'role','marketing','name',full_name,'identifier',employee_id) into r from staff_profiles where id=auth.uid() and active;end if;return r;end$$;

create or replace function public.submit_uniform_request(p_pickup_location uuid,p_items jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare rid uuid:=gen_random_uuid(); ref text; item jsonb; available int; price numeric; total_price numeric:=0;
begin
 if not exists(select 1 from student_profiles where id=auth.uid()) then raise exception 'Student account required';end if;
 if jsonb_array_length(p_items)=0 then raise exception 'At least one item is required';end if;
 ref:='UR-'||extract(year from now())::int||'-'||lpad(nextval('request_reference_seq')::text,5,'0');
 insert into requests(id,reference,student_id,pickup_location_id) values(rid,ref,auth.uid(),p_pickup_location);
 for item in select * from jsonb_array_elements(p_items) loop
   select i.quantity_available,p.price into available,price from inventory i join product_sizes s on s.id=i.size_id join uniform_products p on p.id=s.product_id where i.size_id=(item->>'size_id')::uuid and p.active for update of i;
   if available is null or (item->>'quantity')::int<1 or available<(item->>'quantity')::int then raise exception 'Insufficient inventory';end if;
   insert into request_items(request_id,size_id,quantity,unit_price) values(rid,(item->>'size_id')::uuid,(item->>'quantity')::int,price);total_price:=total_price+price*(item->>'quantity')::int;
 end loop;
 update requests set total=total_price where id=rid;insert into request_status_history(request_id,status,note,changed_by) values(rid,'Pending','Request submitted',auth.uid());insert into audit_logs(actor_id,action,entity_type,entity_id) values(auth.uid(),'request.created','request',rid::text);return jsonb_build_object('id',rid,'reference',ref);end$$;

create or replace function public.transition_request_status(p_request_id uuid,p_new_status request_status,p_note text default null) returns void language plpgsql security definer set search_path=public as $$
declare old_status request_status; owner uuid; allowed boolean:=false; item record;
begin select status,student_id into old_status,owner from requests where id=p_request_id for update;if not found then raise exception 'Request not found';end if;
 if owner=auth.uid() and old_status='Pending' and p_new_status='Cancelled' then allowed:=true;elsif is_marketing() then allowed:=(old_status,p_new_status) in (('Pending','Under Review'),('Under Review','Approved'),('Under Review','Rejected'),('Approved','Preparing'),('Preparing','Ready for Pickup'),('Ready for Pickup','Completed'));end if;
 if not allowed then raise exception 'Invalid or unauthorized status transition';end if;if p_new_status='Rejected' and coalesce(trim(p_note),'')='' then raise exception 'A rejection reason is required';end if;
 if p_new_status='Approved' then for item in select size_id,quantity from request_items where request_id=p_request_id loop update inventory set quantity_available=quantity_available-item.quantity,updated_at=now() where size_id=item.size_id and quantity_available>=item.quantity;if not found then raise exception 'Insufficient stock during approval';end if;insert into inventory_adjustments(size_id,delta,reason,performed_by) values(item.size_id,-item.quantity,'Reserved for '||p_request_id,auth.uid());end loop;end if;
 update requests set status=p_new_status,rejection_reason=case when p_new_status='Rejected' then p_note else rejection_reason end,updated_at=now() where id=p_request_id;insert into request_status_history(request_id,status,note,changed_by) values(p_request_id,p_new_status,p_note,auth.uid());insert into notifications(user_id,title,message) values(owner,'Request '||p_new_status,'Your uniform request is now '||p_new_status||'.');insert into audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'request.status_changed','request',p_request_id::text,jsonb_build_object('from',old_status,'to',p_new_status));end$$;

create or replace function public.adjust_inventory(p_size_id uuid,p_delta integer,p_reason text) returns void language plpgsql security definer set search_path=public as $$begin if not is_marketing() then raise exception 'Not authorized';end if;update inventory set quantity_available=quantity_available+p_delta,updated_at=now() where size_id=p_size_id and quantity_available+p_delta>=0;if not found then raise exception 'Inventory cannot be negative';end if;insert into inventory_adjustments(size_id,delta,reason,performed_by) values(p_size_id,p_delta,p_reason,auth.uid());end$$;

alter table student_profiles enable row level security;alter table staff_profiles enable row level security;alter table uniform_products enable row level security;alter table product_sizes enable row level security;alter table inventory enable row level security;alter table pickup_locations enable row level security;alter table requests enable row level security;alter table request_items enable row level security;alter table request_status_history enable row level security;alter table notifications enable row level security;alter table inventory_adjustments enable row level security;alter table audit_logs enable row level security;
create policy "own student profile" on student_profiles for select using(id=auth.uid() or is_marketing());create policy "own staff profile" on staff_profiles for select using(id=auth.uid());
create policy "authenticated catalog" on uniform_products for select to authenticated using(active or is_marketing());create policy "authenticated sizes" on product_sizes for select to authenticated using(true);create policy "authenticated stock" on inventory for select to authenticated using(true);create policy "active locations" on pickup_locations for select to authenticated using(active or is_marketing());
create policy "request visibility" on requests for select using(student_id=auth.uid() or is_marketing());create policy "item visibility" on request_items for select using(exists(select 1 from requests r where r.id=request_id and (r.student_id=auth.uid() or is_marketing())));create policy "history visibility" on request_status_history for select using(exists(select 1 from requests r where r.id=request_id and (r.student_id=auth.uid() or is_marketing())));create policy "own notifications" on notifications for select using(user_id=auth.uid());create policy "own notification update" on notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "marketing adjustments" on inventory_adjustments for select using(is_marketing());create policy "marketing audits" on audit_logs for select using(is_marketing());
grant execute on function current_user_profile to authenticated;grant execute on function submit_uniform_request to authenticated;grant execute on function transition_request_status to authenticated;grant execute on function adjust_inventory to authenticated;
alter publication supabase_realtime add table requests,notifications,inventory;
